"use client"

import { cva } from "class-variance-authority"

import { Badge } from "@/components/ui/badge"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import type { DataRow } from "@/lib/fable-ui/core"
import type { DataBrowserProps } from "./data-browser.types"
import { useDataBrowserActions } from "./hooks/use-data-browser-actions"
import { useDataBrowserQuery } from "./hooks/use-data-browser-query"
import { useRowDetailSurface } from "./hooks/use-row-detail-surface"
import { getFallbackFilters, getFallbackSortOptions } from "./lib/fallback-filters"
import { InlineError } from "./internal/inline-error"
import { PaginationFooter } from "./internal/pagination-footer"
import { ResponsiveDetailSurface } from "./internal/responsive-detail-surface"
import { TableView } from "./internal/table-view"
import { DataBrowserToolbar } from "./internal/toolbar"

const dataBrowserVariants = cva("w-full overflow-hidden", {
  variants: {
    variant: {
      default: "bg-card shadow-sm",
      elevated: "bg-card shadow-lg shadow-foreground/5",
      subtle: "bg-muted/40 shadow-none",
    },
    size: {
      sm: "",
      md: "",
      lg: "",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
})

const contentGap = {
  sm: "gap-3 p-4",
  md: "gap-4 p-5",
  lg: "gap-5 p-6",
} as const

export function DataBrowser<Row extends DataRow = DataRow>({
  title,
  entityLabel,
  description,
  resourceId,
  searchPlaceholder,
  columns,
  rows = [],
  filters,
  sortOptions,
  initialFilters,
  initialSearch,
  initialSort,
  pageSize = 10,
  rowActions,
  onRowAction,
  onRowActionSuccess,
  renderDetail,
  isLoading,
  isDisabled,
  error,
  variant,
  size = "md",
}: DataBrowserProps<Row>) {
  const effectiveFilters = filters ?? getFallbackFilters(rows, columns)
  const effectiveSortOptions = sortOptions ?? getFallbackSortOptions(columns)
  const detail = useRowDetailSurface<Row>()
  const query = useDataBrowserQuery<Row>({
    resourceId,
    rows,
    columns,
    filters: effectiveFilters,
    sortOptions: effectiveSortOptions,
    initialFilters,
    initialSearch,
    initialSort,
    pageSize,
  })
  const actions = rowActions ?? query.resource?.actions ?? []
  const browserActions = useDataBrowserActions<Row>({
    resourceId,
    onRowAction,
    onRowActionSuccess,
    refetch: query.refetch,
  })
  const busy = Boolean(isLoading || query.isLoading)
  const visibleError = error
    ? error
    : query.error
      ? { title: "Unable to load data", description: query.error.message }
      : undefined
  const totalRows = query.totalRows
  const hasNextPage = Boolean(query.nextCursor || query.page * query.pageSize < totalRows)
  const hasPreviousPage = Boolean(query.previousCursor || query.page > 1)
  const resolvedEntityLabel = entityLabel || query.resource?.entityLabel || "rows"

  return (
    <>
      <Card
        className={cn(dataBrowserVariants({ variant, size }), isDisabled && "opacity-60")}
        data-fable-ui="data-browser"
        aria-busy={busy || undefined}
      >
        <CardHeader>
          <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
            <div className="flex flex-col gap-1">
              <CardTitle className="text-base">{title || query.resource?.label || "Data browser"}</CardTitle>
              {description ? <CardDescription>{description}</CardDescription> : null}
            </div>
            <Badge variant="secondary">
              {totalRows} {totalRows === 1 ? resolvedEntityLabel.replace(/s$/, "") : resolvedEntityLabel}
            </Badge>
          </div>
        </CardHeader>
        <CardContent className={cn("flex flex-col", contentGap[size])}>
          <DataBrowserToolbar
            search={query.state.search}
            searchPlaceholder={searchPlaceholder ?? `Search ${resolvedEntityLabel}`}
            filters={effectiveFilters}
            filterValues={query.state.filters}
            sortOptions={effectiveSortOptions}
            sort={query.state.sort}
            isDisabled={isDisabled}
            onSearchChange={query.setSearch}
            onFilterChange={query.setFilter}
            onSortChange={query.setSort}
            onClearFilters={query.clearFilters}
          />
          {visibleError ? <InlineError title={visibleError.title} description={visibleError.description} /> : null}
          {busy ? <p className="text-sm text-muted-foreground">Loading {resolvedEntityLabel}...</p> : null}
          <TableView
            columns={columns}
            rows={query.rows}
            entityLabel={resolvedEntityLabel}
            isDisabled={isDisabled}
            onOpenRow={renderDetail || actions.length > 0 ? detail.open : undefined}
          />
          <PaginationFooter
            page={query.page}
            pageSize={query.pageSize}
            totalRows={totalRows}
            hasNextPage={hasNextPage}
            hasPreviousPage={hasPreviousPage}
            isDisabled={isDisabled}
            onPageChange={query.setPage}
          />
        </CardContent>
      </Card>
      <ResponsiveDetailSurface
        row={detail.row}
        title={`${title || "Detail"} detail`}
        description={description}
        columns={columns}
        actions={actions}
        actionError={browserActions.actionError}
        pendingActionId={browserActions.pendingActionId}
        renderDetail={renderDetail}
        onClose={detail.close}
        onRunAction={browserActions.runAction}
      />
    </>
  )
}

import type { DataColumn, DataRow } from "@/lib/fable-ui/core"
import { DataBrowser } from "./data-browser"

export function ShowTable({
  title,
  description,
  columns,
  rows,
  isLoading,
  isDisabled,
  error,
}: {
  title: string
  description?: string
  columns: DataColumn[]
  rows: DataRow[]
  isLoading?: boolean
  isDisabled?: boolean
  error?: {
    title: string
    description?: string
  }
}) {
  return (
    <DataBrowser
      title={title}
      description={description}
      entityLabel="rows"
      columns={columns}
      rows={rows}
      pageSize={Math.max(rows.length, 10)}
      isLoading={isLoading}
      isDisabled={isDisabled}
      error={error}
      searchPlaceholder="Search rows"
    />
  )
}

import { tool } from "ai"
import { z } from "zod"

import { DataBrowser } from "@/components/fable-ui/data-browser/data-browser"
import { ShowTable } from "@/components/fable-ui/data-browser/show-table"
import { defineFableComponent, fableRegistry, type DataSourceRegistry } from "@/lib/fable-ui/core"
import { dataColumnSchema, dataFilterSchema, dataSortSchema, sortStateSchema } from "@/lib/fable-ui/core/schemas"
import { resolveDataBrowserIntent } from "./resolve-intent"

const rowSchema = z.record(z.string(), z.unknown())

export const showTableInputSchema = z.object({
  title: z.string().min(1),
  description: z.string().optional(),
  columns: z.array(dataColumnSchema).min(1).max(12),
  rows: z.array(rowSchema).max(50),
})

export type ShowTableInput = z.infer<typeof showTableInputSchema>

export const showDataBrowserInputSchema = z.object({
  title: z.string().min(1),
  entityLabel: z.string().min(1).optional(),
  description: z.string().optional(),
  resourceId: z
    .string()
    .min(1)
    .optional()
    .describe(
      "Use only a resource id from fableRegistry.getAgentResourceManifest(). Never invent resource ids.",
    ),
  searchPlaceholder: z.string().optional(),
  columns: z.array(dataColumnSchema).optional(),
  rows: z.array(rowSchema).max(50).optional(),
  filters: z.array(dataFilterSchema).optional(),
  sortOptions: z.array(dataSortSchema).optional(),
  initialFilters: z.record(z.string(), z.unknown()).optional(),
  initialSort: sortStateSchema.optional(),
  initialSearch: z.string().optional(),
  visibleColumns: z.array(z.string().min(1)).optional(),
  detail: z
    .object({
      title: z.string().optional(),
      description: z.string().optional(),
      fields: z.array(z.string()).optional(),
    })
    .optional(),
  actionIntents: z
    .array(
      z.object({
        actionId: z.string().min(1),
        rowId: z.string().optional(),
      }),
    )
    .optional(),
  pageSize: z.number().int().positive().max(100).optional(),
})

export type ShowDataBrowserInput = z.infer<typeof showDataBrowserInputSchema>

export function describeAvailableResources(registry: DataSourceRegistry = fableRegistry) {
  return JSON.stringify(registry.getAgentResourceManifest(), null, 2)
}

export function createShowTableTool() {
  return tool({
    description:
      "Show a small static table snapshot when display-ready rows are already available. Limit rows to about 50. Do not use for raw SQL, raw Firestore paths, secrets, or authorization decisions.",
    inputSchema: showTableInputSchema,
    execute: async (input) => input,
  })
}

export const showTableTool = createShowTableTool()

export function createShowDataBrowserTool() {
  return tool({
    description: [
      "Show a trusted data browser for search, filters, sort, pagination, or row detail.",
      "Use resourceId only from fableRegistry.getAgentResourceManifest(); never invent resource IDs.",
      "Never pass raw SQL, raw Firestore paths, raw collection names, secrets, or authorization decisions.",
      "The host owns data access, permissions, validation, allowed filters, allowed sorts, and row actions.",
      "If no resourceId is available, include safe static rows and columns only when the data is already present.",
    ].join(" "),
    inputSchema: showDataBrowserInputSchema,
    execute: async (input) => input,
  })
}

export const showDataBrowserTool = createShowDataBrowserTool()

export const showTable = defineFableComponent({
  name: "show_table",
  schema: showTableInputSchema,
  tool: showTableTool,
  renderer: {
    Component: ShowTable,
    loadingProps: { title: "Table", columns: [], rows: [], isLoading: true },
    emptyProps: { title: "Table", columns: [], rows: [] },
    errorProps: (description: string) => ({
      title: "Table unavailable",
      columns: [],
      rows: [],
      error: { title: "Table unavailable", description },
    }),
    toProps: (data: ShowTableInput) => ({ ...data }),
  },
})

export const showDataBrowser = defineFableComponent({
  name: "show_data_browser",
  schema: showDataBrowserInputSchema,
  tool: showDataBrowserTool,
  renderer: {
    Component: DataBrowser,
    loadingProps: {
      title: "Data browser",
      entityLabel: "rows",
      columns: [],
      rows: [],
      isLoading: true,
    },
    emptyProps: { title: "Data browser", entityLabel: "rows", columns: [], rows: [] },
    errorProps: (description: string) => ({
      title: "Data browser unavailable",
      entityLabel: "rows",
      columns: [],
      rows: [],
      error: { title: "Data browser unavailable", description },
    }),
    toProps: (data: ShowDataBrowserInput) => resolveDataBrowserIntent(data),
  },
})

import * as React from "react"

import { queryLocalRows, useOptionalFableDataContext, fableRegistry, type DataColumn, type DataFilter, type DataQueryResult, type DataRow, type DataSort, type SortState } from "@/lib/fable-ui/core"
import type { DataBrowserQueryState } from "../data-browser.types"

export function useDataBrowserQuery<Row extends DataRow>({
  resourceId,
  rows = [],
  columns,
  initialFilters = {},
  initialSearch = "",
  initialSort,
  pageSize = 10,
}: {
  resourceId?: string
  rows?: Row[]
  columns: DataColumn[]
  filters?: DataFilter[]
  sortOptions?: DataSort[]
  initialFilters?: Record<string, unknown>
  initialSearch?: string
  initialSort?: SortState
  pageSize?: number
}) {
  const dataContext = useOptionalFableDataContext()
  const registry = dataContext?.registry ?? fableRegistry
  const context = dataContext?.context ?? {}
  const [state, setState] = React.useState<DataBrowserQueryState>({
    search: initialSearch,
    filters: initialFilters,
    sort: initialSort,
    page: 1,
    pageSize,
  })
  const [remoteResult, setRemoteResult] = React.useState<DataQueryResult<Row> | null>(null)
  const [isLoading, setIsLoading] = React.useState(false)
  const [error, setError] = React.useState<Error | undefined>()
  const [revision, setRevision] = React.useState(0)

  const resource = resourceId ? registry.getResource(resourceId) : undefined

  const query = React.useMemo(
    () => ({
      search: state.search,
      filters: state.filters,
      sort: state.sort,
      page: state.page,
      pageSize: state.pageSize,
      cursor: state.cursor,
    }),
    [state],
  )

  React.useEffect(() => {
    if (!resourceId) {
      return
    }

    let isActive = true
    setIsLoading(true)
    setError(undefined)

    registry
      .list<Row>(resourceId, query, context)
      .then((result) => {
        if (isActive) {
          setRemoteResult(result)
        }
      })
      .catch((nextError) => {
        if (isActive) {
          setError(nextError instanceof Error ? nextError : new Error("Unable to load resource."))
        }
      })
      .finally(() => {
        if (isActive) {
          setIsLoading(false)
        }
      })

    return () => {
      isActive = false
    }
  }, [context, query, registry, resourceId, revision])

  const localResult = React.useMemo(() => {
    if (resourceId) {
      return null
    }

    return queryLocalRows(rows, query, columns)
  }, [columns, query, resourceId, rows])

  const result = resourceId ? remoteResult : localResult

  const updateState = React.useCallback((next: Partial<DataBrowserQueryState>) => {
    setState((current) => ({ ...current, ...next, page: next.page ?? 1, cursor: next.cursor }))
  }, [])

  return {
    resource,
    state,
    setSearch: (search: string) => updateState({ search }),
    setFilter: (key: string, value: unknown) =>
      updateState({ filters: { ...state.filters, [key]: value } }),
    clearFilters: () => updateState({ filters: {} }),
    setSort: (sort?: SortState) => updateState({ sort }),
    setPage: (page: number) =>
      setState((current) => ({
        ...current,
        page,
        cursor:
          page > current.page
            ? result?.nextCursor
            : page < current.page
              ? result?.previousCursor
              : current.cursor,
      })),
    result,
    rows: result?.rows ?? [],
    totalRows: result?.totalRows ?? 0,
    page: result?.page ?? state.page,
    pageSize: result?.pageSize ?? state.pageSize,
    nextCursor: result?.nextCursor,
    previousCursor: result?.previousCursor,
    isLoading,
    error,
    refetch: () => setRevision((value) => value + 1),
  }
}

import * as React from "react"

import { getDataBrowserRowId } from "../lib/get-row-id"
import type { DataBrowserRowAction } from "../data-browser.types"
import { useOptionalFableDataContext, fableRegistry, type DataRow } from "@/lib/fable-ui/core"

export function useDataBrowserActions<Row extends DataRow>({
  resourceId,
  onRowAction,
  onRowActionSuccess,
  refetch,
}: {
  resourceId?: string
  onRowAction?: (
    action: DataBrowserRowAction<Row>,
    row: Row,
    values?: Record<string, unknown>,
  ) => Promise<unknown> | unknown
  onRowActionSuccess?: (result: unknown, action: DataBrowserRowAction<Row>, row: Row) => void
  refetch?: () => void
}) {
  const dataContext = useOptionalFableDataContext()
  const registry = dataContext?.registry ?? fableRegistry
  const context = dataContext?.context ?? {}
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(null)
  const [error, setError] = React.useState<string | null>(null)

  const runAction = React.useCallback(
    async (action: DataBrowserRowAction<Row>, row: Row, values?: Record<string, unknown>) => {
      setError(null)
      setPendingActionId(action.id)

      try {
        const result = action.run
          ? await action.run(row, values)
          : onRowAction
            ? await onRowAction(action, row, values)
            : resourceId
              ? await registry.executeAction(
                  {
                    actionId: action.id,
                    resourceId,
                    rowId: getDataBrowserRowId(row),
                    values,
                  },
                  context,
                )
              : undefined

        onRowActionSuccess?.(result, action, row)
        refetch?.()
        return result
      } catch (nextError) {
        const message = nextError instanceof Error ? nextError.message : "The action failed."
        setError(message)
        return undefined
      } finally {
        setPendingActionId(null)
      }
    },
    [context, onRowAction, onRowActionSuccess, refetch, registry, resourceId],
  )

  return {
    runAction,
    pendingActionId,
    actionError: error,
  }
}

import * as React from "react"

import type { DataRow } from "@/lib/fable-ui/core"

export function useRowDetailSurface<Row extends DataRow>() {
  const [row, setRow] = React.useState<Row | null>(null)

  return {
    row,
    isOpen: Boolean(row),
    open: setRow,
    close: () => setRow(null),
  }
}

export function InlineError({
  title,
  description,
}: {
  title: string
  description?: string
}) {
  return (
    <div className="rounded-md border border-destructive/20 bg-destructive/5 p-3">
      <p className="text-sm font-medium text-destructive">{title}</p>
      {description ? <p className="text-sm text-muted-foreground">{description}</p> : null}
    </div>
  )
}

import type { DataColumn, DataRow } from "@/lib/fable-ui/core"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer"
import * as React from "react"
import type { DataBrowserRowAction } from "../data-browser.types"
import { RowDetail } from "./row-detail"

function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState(false)

  React.useEffect(() => {
    const query = window.matchMedia("(max-width: 767px)")
    const update = () => setIsMobile(query.matches)

    update()
    query.addEventListener("change", update)

    return () => query.removeEventListener("change", update)
  }, [])

  return isMobile
}

export function ResponsiveDetailSurface<Row extends DataRow>({
  row,
  title,
  description,
  columns,
  actions,
  actionError,
  pendingActionId,
  renderDetail,
  onClose,
  onRunAction,
}: {
  row: Row | null
  title: string
  description?: string
  columns: DataColumn[]
  actions: DataBrowserRowAction<Row>[]
  actionError?: string | null
  pendingActionId?: string | null
  renderDetail?: (row: Row) => React.ReactNode
  onClose: () => void
  onRunAction: (action: DataBrowserRowAction<Row>, row: Row, values?: Record<string, unknown>) => void
}) {
  const isMobile = useIsMobile()
  const isOpen = Boolean(row)

  if (isMobile) {
    return (
      <Drawer open={isOpen} onOpenChange={(open) => (!open ? onClose() : undefined)}>
        <DrawerContent>
          <DrawerHeader>
            <DrawerTitle>{title}</DrawerTitle>
            {description ? <DrawerDescription>{description}</DrawerDescription> : null}
          </DrawerHeader>
          <div className="max-h-[70vh] overflow-y-auto px-4 pb-4">
            {row ? (
              <RowDetail
                row={row}
                columns={columns}
                actions={actions}
                actionError={actionError}
                pendingActionId={pendingActionId}
                renderDetail={renderDetail}
                onRunAction={onRunAction}
              />
            ) : null}
          </div>
        </DrawerContent>
      </Drawer>
    )
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => (!open ? onClose() : undefined)}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {description ? <DialogDescription>{description}</DialogDescription> : null}
        </DialogHeader>
        {row ? (
          <RowDetail
            row={row}
            columns={columns}
            actions={actions}
            actionError={actionError}
            pendingActionId={pendingActionId}
            renderDetail={renderDetail}
            onRunAction={onRunAction}
          />
        ) : null}
      </DialogContent>
    </Dialog>
  )
}

import * as React from "react"

import { formatDataCell, type DataColumn, type DataRow } from "@/lib/fable-ui/core"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import type { DataBrowserRowAction } from "../data-browser.types"

export function RowDetail<Row extends DataRow>({
  row,
  columns,
  actions,
  actionError,
  pendingActionId,
  renderDetail,
  onRunAction,
}: {
  row: Row
  columns: DataColumn[]
  actions: DataBrowserRowAction<Row>[]
  actionError?: string | null
  pendingActionId?: string | null
  renderDetail?: (row: Row) => React.ReactNode
  onRunAction: (action: DataBrowserRowAction<Row>, row: Row, values?: Record<string, unknown>) => void
}) {
  const [actionValues, setActionValues] = React.useState<Record<string, Record<string, unknown>>>({})

  if (renderDetail) {
    return <>{renderDetail(row)}</>
  }

  return (
    <div className="flex flex-col gap-4">
      <dl className="grid gap-3 sm:grid-cols-2">
        {columns
          .filter((column) => !column.hidden)
          .map((column) => (
            <div key={column.key} className="rounded-md bg-muted/50 p-3">
              <dt className="text-xs text-muted-foreground">{column.label}</dt>
              <dd className="mt-1 text-sm font-medium">{formatDataCell(row, column)}</dd>
            </div>
          ))}
      </dl>
      {actionError ? (
        <div className="rounded-md border border-destructive/20 bg-destructive/5 p-3 text-sm text-destructive">
          {actionError}
        </div>
      ) : null}
      {actions.length > 0 ? (
        <div className="flex flex-col gap-3">
          {actions.map((action) => {
            const values = actionValues[action.id] ?? {}

            return (
              <div key={action.id} className="rounded-md border p-3">
                <div className="flex flex-col gap-2">
                  <p className="text-sm font-medium">{action.label}</p>
                  {action.description ? (
                    <p className="text-xs text-muted-foreground">{action.description}</p>
                  ) : null}
                  {action.fields?.map((field) => (
                    <label key={field.name} className="flex flex-col gap-1 text-xs font-medium">
                      {field.label}
                      <Input
                        value={String(values[field.name] ?? "")}
                        onChange={(event) =>
                          setActionValues((current) => ({
                            ...current,
                            [action.id]: {
                              ...values,
                              [field.name]: event.target.value,
                            },
                          }))
                        }
                      />
                    </label>
                  ))}
                  <Button
                    type="button"
                    variant={action.variant === "destructive" ? "destructive" : "default"}
                    size="sm"
                    disabled={pendingActionId === action.id}
                    onClick={() => onRunAction(action, row, values)}
                  >
                    {pendingActionId === action.id ? "Running..." : action.label}
                  </Button>
                </div>
              </div>
            )
          })}
        </div>
      ) : null}
    </div>
  )
}

import { formatDataCell, type DataColumn, type DataRow } from "@/lib/fable-ui/core"
import { Button } from "@/components/ui/button"
import { getDataBrowserRowId } from "../lib/get-row-id"

export function TableView<Row extends DataRow>({
  columns,
  rows,
  entityLabel,
  isDisabled,
  onOpenRow,
}: {
  columns: DataColumn[]
  rows: Row[]
  entityLabel: string
  isDisabled?: boolean
  onOpenRow?: (row: Row) => void
}) {
  const visibleColumns = columns.filter((column) => !column.hidden)

  return (
    <div className="overflow-x-auto rounded-md border">
      <table className="w-full table-fixed text-sm">
        <thead className="bg-muted/60">
          <tr>
            {visibleColumns.map((column) => (
              <th
                key={column.key}
                className="px-3 py-2 text-left font-medium"
                data-align={column.align ?? "left"}
              >
                {column.label}
              </th>
            ))}
            {onOpenRow ? <th className="w-28 px-3 py-2 text-right font-medium">Detail</th> : null}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td className="px-3 py-8 text-center text-muted-foreground" colSpan={visibleColumns.length + 1}>
                No {entityLabel} to display.
              </td>
            </tr>
          ) : (
            rows.map((row, index) => (
              <tr key={getDataBrowserRowId(row, index)} className="border-t">
                {visibleColumns.map((column) => (
                  <td
                    key={`${getDataBrowserRowId(row, index)}-${column.key}`}
                    className="truncate px-3 py-2"
                  >
                    {formatDataCell(row, column)}
                  </td>
                ))}
                {onOpenRow ? (
                  <td className="px-3 py-2 text-right">
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      disabled={isDisabled}
                      onClick={() => onOpenRow(row)}
                    >
                      Open
                    </Button>
                  </td>
                ) : null}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  )
}

import { SearchIcon } from "lucide-react"

import type { DataFilter, DataSort, SortState } from "@/lib/fable-ui/core"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

function getOptionValue(option: string | { value: string | number | boolean }) {
  return typeof option === "string" ? option : String(option.value)
}

function getOptionLabel(option: string | { label: string }) {
  return typeof option === "string" ? option : option.label
}

export function DataBrowserToolbar({
  search,
  searchPlaceholder,
  filters,
  filterValues,
  sortOptions,
  sort,
  isDisabled,
  onSearchChange,
  onFilterChange,
  onSortChange,
  onClearFilters,
}: {
  search: string
  searchPlaceholder: string
  filters: DataFilter[]
  filterValues: Record<string, unknown>
  sortOptions: DataSort[]
  sort?: SortState
  isDisabled?: boolean
  onSearchChange: (value: string) => void
  onFilterChange: (key: string, value: unknown) => void
  onSortChange: (sort?: SortState) => void
  onClearFilters: () => void
}) {
  const hasFilters = Object.values(filterValues).some((value) => value != null && value !== "")

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col gap-2 sm:flex-row">
        <label className="relative flex-1">
          <SearchIcon size={18} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            placeholder={searchPlaceholder}
            disabled={isDisabled}
            className="pl-9"
            onChange={(event) => onSearchChange(event.target.value)}
          />
        </label>
        {sortOptions.length > 0 ? (
          <Select
            value={sort ? `${sort.key}:${sort.direction}` : ""}
            disabled={isDisabled}
            onValueChange={(value) => {
              if (!value) {
                onSortChange(undefined)
                return
              }

              const [key, direction] = value.split(":")
              onSortChange({ key, direction: direction === "desc" ? "desc" : "asc" })
            }}
          >
            <SelectTrigger className="w-full sm:w-48">
              <SelectValue placeholder="Sort" />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                {sortOptions.flatMap((option) =>
                  (option.directions ?? ["asc", "desc"]).map((direction) => (
                    <SelectItem key={`${option.key}:${direction}`} value={`${option.key}:${direction}`}>
                      {option.label} {direction === "asc" ? "asc" : "desc"}
                    </SelectItem>
                  )),
                )}
              </SelectGroup>
            </SelectContent>
          </Select>
        ) : null}
      </div>
      {filters.length > 0 ? (
        <div className="flex flex-wrap gap-2">
          {filters.map((filter) => {
            if (filter.type === "select" && filter.options?.length) {
              return (
                <Select
                  key={filter.key}
                  value={String(filterValues[filter.key] ?? "")}
                  disabled={isDisabled}
                  onValueChange={(value) => onFilterChange(filter.key, value)}
                >
                  <SelectTrigger className="w-44">
                    <SelectValue placeholder={filter.label} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      {filter.options.map((option) => (
                        <SelectItem key={getOptionValue(option)} value={getOptionValue(option)}>
                          {getOptionLabel(option)}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
              )
            }

            return (
              <Input
                key={filter.key}
                value={String(filterValues[filter.key] ?? "")}
                placeholder={filter.label}
                disabled={isDisabled}
                className="w-44"
                onChange={(event) => onFilterChange(filter.key, event.target.value)}
              />
            )
          })}
          {hasFilters ? (
            <Button type="button" variant="ghost" size="sm" disabled={isDisabled} onClick={onClearFilters}>
              Clear
            </Button>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

import { getDataValue, type DataColumn, type DataFilter, type DataRow, type DataSort } from "@/lib/fable-ui/core"

const fallbackFilterKeys = new Set(["status", "type", "category", "role"])

export function getFallbackFilters(rows: DataRow[], columns: DataColumn[]): DataFilter[] {
  return columns
    .filter((column) => column.filterable || fallbackFilterKeys.has(column.key))
    .map((column) => {
      const values = Array.from(
        new Set(
          rows
            .map((row) => getDataValue(row, column.key))
            .filter((value) => value != null && value !== "")
            .map(String),
        ),
      ).slice(0, 20)

      return {
        key: column.key,
        label: column.label,
        type: values.length > 0 ? "select" : "text",
        options: values,
      } satisfies DataFilter
    })
}

export function getFallbackSortOptions(columns: DataColumn[]): DataSort[] {
  return columns
    .filter((column) => column.sortable !== false)
    .map((column) => ({
      key: column.key,
      label: column.label,
      directions: ["asc", "desc"],
    }))
}

import { getRowId as getCoreRowId, type DataRow } from "@/lib/fable-ui/core"

export function getDataBrowserRowId(row: DataRow, index = 0) {
  return getCoreRowId(row) ?? String(index)
}
